#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
int main() {
    std::ifstream input{"records.txt"};
    if (!input) { std::cout << "missing\n"; return 0; }
    std::string line;
    int count{};
    long long sum{};
    while (std::getline(input, line)) {
        if (++count > 100 || line.size() > 200) { std::cout << "invalid\n"; return 0; }
        std::istringstream parser{line};
        int value{};
        if (!(parser >> value) || value < -1000 || value > 1000) { std::cout << "invalid\n"; return 0; }
        parser >> std::ws;
        if (!parser.eof()) { std::cout << "invalid\n"; return 0; }
        sum += value;
    }
    if (input.bad() || (!input.eof() && input.fail())) { std::cout << "invalid\n"; return 0; }
    std::ofstream output{"report.txt"};
    output << count << ' ' << sum << '\n';
    output.close();
    if (!output) { std::cout << "write-error\n"; return 0; }
    std::cout << "exported\n";
}

